def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Find bounded zero regions and their adjacent 1 boundary pixels.
    seen = set()
    holes = []
    for r in range(h):
        for c in range(w):
            if g[r][c] != 0 or (r,c) in seen:
                continue
            q = [(r,c)]; seen.add((r,c)); cells=[]; touches_edge=False
            for y,x in q:
                cells.append((y,x))
                if y == 0 or x == 0 or y == h-1 or x == w-1:
                    touches_edge=True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0 <= ny < h and 0 <= nx < w and g[ny][nx] == 0 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            if not touches_edge:
                boundary=set()
                for y,x in cells:
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0 <= ny < h and 0 <= nx < w and g[ny][nx] == 1:
                            boundary.add((ny,nx))
                holes.append((cells,boundary))
    # Compute vertex-biconnected blocks in the 4-neighbor graph of 1 cells.
    ones={(r,c) for r in range(h) for c in range(w) if g[r][c] == 1}
    adj={p:[(p[0]+dy,p[1]+dx) for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)) if (p[0]+dy,p[1]+dx) in ones] for p in ones}
    disc={}; low={}; stack=[]; blocks=[]; clock=0
    def dfs(u, parent=None):
        nonlocal clock
        clock += 1; disc[u]=low[u]=clock
        for v in adj[u]:
            if v == parent: continue
            if v not in disc:
                stack.append((u,v)); dfs(v,u); low[u]=min(low[u],low[v])
                if low[v] >= disc[u]:
                    block=set()
                    while stack:
                        e=stack.pop(); block.update(e)
                        if e == (u,v): break
                    blocks.append(block)
            elif disc[v] < disc[u]:
                stack.append((u,v)); low[u]=min(low[u],disc[v])
    for p in ones:
        if p not in disc: dfs(p)
    for cells,boundary in holes:
        # Paint the inner one-cell rim of the enclosed zero region.
        rim=set()
        for y,x in cells:
            if any(0 <= y+dy < h and 0 <= x+dx < w and g[y+dy][x+dx] == 1 for dy,dx in ((1,0),(-1,0),(0,1),(0,-1))):
                rim.add((y,x))
        for y,x in rim: g[y][x]=3
        # The contour is the biconnected block with the most contact with this hole.
        scored=[(len(b & boundary), b) for b in blocks]
        if scored:
            score,best=max(scored,key=lambda z:z[0])
            if score:
                rs=[p[0] for p in best]; cs=[p[1] for p in best]
                r0,r1=min(rs)-1,max(rs)+1; c0,c1=min(cs)-1,max(cs)+1
                for y in range(max(0,r0),min(h-1,r1)+1):
                    for x in range(max(0,c0),min(w-1,c1)+1):
                        if y in (r0,r1) or x in (c0,c1):
                            if g[y][x] == 0: g[y][x]=2
